import{_ as t,o as a,c as e,aw as l}from"./chunks/framework.DLufY-ao.js";const h=JSON.parse('{"title":"Эстимация","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/agile/concepts/estimation.md","filePath":"wiki/dev-commit/theory/agile/concepts/estimation.md"}'),o={name:"wiki/dev-commit/theory/agile/concepts/estimation.md"};function r(n,i,s,m,u,d){return a(),e("div",null,[...i[0]||(i[0]=[l('<h1 id="эстимация" tabindex="-1">Эстимация <a class="header-anchor" href="#эстимация" aria-label="Permalink to &quot;Эстимация&quot;">​</a></h1><ul><li>Эстимация - оценки сроков и стоимости проекта</li></ul><h3 id="_1-экспертная-оценка-expert-judgement" tabindex="-1">1. Экспертная оценка (Expert Judgement) <a class="header-anchor" href="#_1-экспертная-оценка-expert-judgement" aria-label="Permalink to &quot;1. Экспертная оценка (Expert Judgement)&quot;">​</a></h3><ul><li>Формирование оценки с привлечением экспертов в данной требуемой области</li><li>Эксперты выдвигают свои предположения по поводу оценки (сроков или стоимости). После этого можно усреднить все предложения, а можно постараться прийти к единому решению в ходе дискуссии</li></ul><h3 id="_2-метод-оценки-по-3-точкам-three-point-estimation" tabindex="-1">2. Метод оценки по 3 точкам (Three Point Estimation) <a class="header-anchor" href="#_2-метод-оценки-по-3-точкам-three-point-estimation" aria-label="Permalink to &quot;2. Метод оценки по 3 точкам (Three Point Estimation)&quot;">​</a></h3><ul><li>Сначала определяются оптимистичная (O = Optimistic), пессимистичная (P = Pessimistic) и реалистичная\\средняя (M = Middle) оценки</li><li>Значения P, M и O определяются экспертно (в часах, днях, $). Для этого задаются вопросы типа: «сколько времени займет проект, если все пойдет хорошо?», «каким может быть самый негативный сценарий и сколько на него потребуется времени\\усилий?» и т.д.</li><li>Далее полученные значения P, M и O подставляются в формулу: (O + 4 M + P) / 6</li><li>Результат расчета дает усредненную оценку. Такая формула позволяет с одной стороны учесть возможные позитивные и негативные сценарии, а с другой – «сгладить» их влияние и получить более реальное значение оценки</li></ul><h3 id="_3-стоимость-качества-cost-of-quality" tabindex="-1">3. Стоимость качества (Cost of Quality) <a class="header-anchor" href="#_3-стоимость-качества-cost-of-quality" aria-label="Permalink to &quot;3. Стоимость качества (Cost of Quality)&quot;">​</a></h3><ul><li><p>Сначала оценивается время / бюджет только на разработку функционала, без учета ошибок и проблем, как если бы у нас сразу получалось идеальное ПО без дефектов. А далее оценивается сколько дополнительного времени и бюджета потребуется на работу с ошибками и проблемами в реальности, чтобы приблизить ПО к тому самому «идеальному» состоянию</p></li><li><p>При оценке затрат на обеспечение качества ПО можно проанализировать и учесть такие области:</p><ul><li>расходы на активности по предотвращению дефектов</li><li>стоимость тестирования</li><li>исправление внутренних ошибок</li><li>исправление внешних проблем по интеграции</li><li>затраты на установку и настройку ПО с учетом реальной среды и данных</li></ul></li></ul><h3 id="_4-оценка-по-аналогиям-analogous-estimation" tabindex="-1">4. Оценка по аналогиям (Analogous Estimation) <a class="header-anchor" href="#_4-оценка-по-аналогиям-analogous-estimation" aria-label="Permalink to &quot;4. Оценка по аналогиям (Analogous Estimation)&quot;">​</a></h3><ul><li>Можно опираться на прошлый опыт решения подобных задач или проектов</li><li>Чтобы найти знакомые или похожие на предыдущий опыт задачи можно сделать декомпозицию</li></ul><h3 id="_5-оценка-по-параметрам-и-моделирование-parametric-model" tabindex="-1">5. Оценка по параметрам и моделирование (Parametric Model) <a class="header-anchor" href="#_5-оценка-по-параметрам-и-моделирование-parametric-model" aria-label="Permalink to &quot;5. Оценка по параметрам и моделирование (Parametric Model)&quot;">​</a></h3><ul><li>Один из самых точных и гибких методов оценки. Его суть в том, чтобы построить некую параметризированную модель-прогноз взяв за основу прошлый опыт, имеющиеся данные и метрики, статистику</li><li>Фактически строится специальная математическая модель, которая позволяет отслеживать как меняется итоговая оценка в зависимости от исходных параметров</li></ul><h3 id="_6-оценка-от-частного-к-общему-bottom-up-estimation" tabindex="-1">6. Оценка от частного к общему (Bottom-up Estimation) <a class="header-anchor" href="#_6-оценка-от-частного-к-общему-bottom-up-estimation" aria-label="Permalink to &quot;6. Оценка от частного к общему (Bottom-up Estimation)&quot;">​</a></h3><ul><li>Метод похож на экспертную оценку, только в данном случае прогноз делается не для всего проекта в целом, а отдельно для составляющих его задач. Как это выглядит: мы собираем экспертное мнение, например, у специалистов по анализу, разработке, тестированию, поддержке ПО. Суммируем их оценки вместе, добавляем к ним затраты времени на взаимодействие и формируем общий прогноз</li><li>Другими словами, мы собираем оценку по частям, узнавая сколько необходимо времени каждому из участников процесса разработки ПО и сводим все воедино с учетом дополнительных рисков</li></ul>',14)])])}const _=t(o,[["render",r]]);export{h as __pageData,_ as default};
